  RAISE EXCEPTION 'noncanonical PDF record scalar kind %',p_kind USING ERRCODE='23514';
 END IF;
 RETURN convert_to(p_kind,'UTF8') || int8send(octet_length(p_payload)::bigint) ||
  ops.pdf_identity_byte_root(p_payload);
