DECLARE b ops.pdf_stage_build; contract_ text; result_ text:=''; prior_ text; reused_ text;
BEGIN
 IF NOT (current_setting('transaction_isolation')=ANY(ARRAY['read committed']::text[])) THEN
 RAISE EXCEPTION 'PDF projection admission requires READ COMMITTED' USING ERRCODE='25000'; END IF;
 IF p_check='seal' THEN
  PERFORM ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
  PERFORM 1 FROM ops.pdf_stage_build WHERE build_id=p_build FOR NO KEY UPDATE;
 END IF;
 b:=ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 PERFORM ops.require_pdf_operation(b.release_id,'validate_pdf_build');
 IF b.state<>'frozen' THEN RAISE EXCEPTION 'PDF check requires a frozen private build'; END IF;
 contract_:=ops.pdf_validation_contract(b.release_id);
 IF p_check='seal' THEN
  IF NOT EXISTS(SELECT FROM ops.pdf_native_validation v WHERE v.build_id=p_build
   AND v.frozen_digest=p_frozen AND v.contract_digest=contract_ AND v.passed) THEN
   RAISE EXCEPTION 'native callback conformance outcome missing or stale' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT FROM ops.pdf_validation_check v WHERE v.build_id=p_build
   AND v.attempt=p_attempt AND v.holder=p_holder AND v.frozen_digest=p_frozen
   AND v.contract_digest=contract_ AND v.check_name='seal') THEN RETURN; END IF;
  SELECT p.build_id INTO reused_ FROM ops.pdf_published_revision p
  JOIN ops.pdf_build_validation v ON v.build_id=p.build_id AND v.frozen_digest=p.frozen_digest
   AND v.logical_digest=p.logical_digest AND v.native_contract_digest=contract_
   AND v.native_callbacks
  JOIN ops.task t ON t.id=p.task_id
  JOIN LATERAL ops.pdf_task_context(t.id) previous_context ON true
  JOIN ops.pdf_frozen_build f ON f.build_id=p_build AND f.kind=p.kind
  WHERE EXISTS(
   SELECT FROM ops.data_derivation episode WHERE episode.producer_task_id=t.id
   AND ops.ddo_support_valid(episode.id))
   AND p.source_digest=b.source_digest AND p.schema_digest=b.schema_digest
   AND p.recipe_digest=b.recipe_digest AND p.release_id=b.release_id
   AND previous_context.project_id=(SELECT project_id FROM ops.pdf_task_context(b.task_id))
  ORDER BY t.id DESC LIMIT 1;
 ELSE
  SELECT v.predecessor_build_id INTO prior_ FROM ops.pdf_validation_check v WHERE v.build_id=p_build
   AND v.attempt=p_attempt AND v.holder=p_holder AND v.frozen_digest=p_frozen
   AND v.contract_digest=contract_ AND v.check_name='seal';
  IF NOT FOUND THEN
   RAISE EXCEPTION 'PDF projection seal missing or stale' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT FROM ops.pdf_validation_check v WHERE v.build_id=p_build
   AND v.attempt=p_attempt AND v.holder=p_holder AND v.frozen_digest=p_frozen
   AND v.contract_digest=contract_ AND v.check_name=p_check) THEN RETURN; END IF;
  CASE p_check
   WHEN 'inventory' THEN PERFORM ops.pdf_check_build_inventory(p_build,b.source_digest,
   (SELECT project_id FROM ops.pdf_task_context(b.task_id)));
   WHEN 'access' THEN
    IF prior_ IS NOT NULL AND NOT EXISTS((SELECT "pointer","ordinal","label","parent_pointer","section_pointer","content_layer","text",convert_to("native_json"::text,'UTF8') FROM kb.pdf_record_access WHERE product_id=p_build AND revision_id=p_build EXCEPT ALL SELECT "pointer","ordinal","label","parent_pointer","section_pointer","content_layer","text",convert_to("native_json"::text,'UTF8') FROM kb.pdf_record_access WHERE product_id=prior_ AND revision_id=prior_) UNION ALL (SELECT "pointer","ordinal","label","parent_pointer","section_pointer","content_layer","text",convert_to("native_json"::text,'UTF8') FROM kb.pdf_record_access WHERE product_id=prior_ AND revision_id=prior_ EXCEPT ALL SELECT "pointer","ordinal","label","parent_pointer","section_pointer","content_layer","text",convert_to("native_json"::text,'UTF8') FROM kb.pdf_record_access WHERE product_id=p_build AND revision_id=p_build))
 AND NOT EXISTS((SELECT "pointer","region_index","page_no",convert_to("page_width"::text,'UTF8'),convert_to("page_height"::text,'UTF8'),convert_to("left"::text,'UTF8'),convert_to("top"::text,'UTF8'),convert_to("right"::text,'UTF8'),convert_to("bottom"::text,'UTF8'),"origin" FROM kb.pdf_record_region WHERE product_id=p_build AND revision_id=p_build EXCEPT ALL SELECT "pointer","region_index","page_no",convert_to("page_width"::text,'UTF8'),convert_to("page_height"::text,'UTF8'),convert_to("left"::text,'UTF8'),convert_to("top"::text,'UTF8'),convert_to("right"::text,'UTF8'),convert_to("bottom"::text,'UTF8'),"origin" FROM kb.pdf_record_region WHERE product_id=prior_ AND revision_id=prior_) UNION ALL (SELECT "pointer","region_index","page_no",convert_to("page_width"::text,'UTF8'),convert_to("page_height"::text,'UTF8'),convert_to("left"::text,'UTF8'),convert_to("top"::text,'UTF8'),convert_to("right"::text,'UTF8'),convert_to("bottom"::text,'UTF8'),"origin" FROM kb.pdf_record_region WHERE product_id=prior_ AND revision_id=prior_ EXCEPT ALL SELECT "pointer","region_index","page_no",convert_to("page_width"::text,'UTF8'),convert_to("page_height"::text,'UTF8'),convert_to("left"::text,'UTF8'),convert_to("top"::text,'UTF8'),convert_to("right"::text,'UTF8'),convert_to("bottom"::text,'UTF8'),"origin" FROM kb.pdf_record_region WHERE product_id=p_build AND revision_id=p_build)) AND NOT EXISTS((SELECT "release_id","source_digest","mapping_profile","contract_version","native_schema_digest","root_id" FROM ops.pdf_record_document WHERE product_id=p_build AND revision_id=p_build EXCEPT ALL SELECT "release_id","source_digest","mapping_profile","contract_version","native_schema_digest","root_id" FROM ops.pdf_record_document WHERE product_id=prior_ AND revision_id=prior_) UNION ALL (SELECT "release_id","source_digest","mapping_profile","contract_version","native_schema_digest","root_id" FROM ops.pdf_record_document WHERE product_id=prior_ AND revision_id=prior_ EXCEPT ALL SELECT "release_id","source_digest","mapping_profile","contract_version","native_schema_digest","root_id" FROM ops.pdf_record_document WHERE product_id=p_build AND revision_id=p_build))
 AND NOT EXISTS((SELECT "record_id","native_type","family","native_address","native_address_stream_id",convert_to("scalars_json"::text,'UTF8'),convert_to("structure_json"::text,'UTF8') FROM kb.pdf_record_native WHERE product_id=p_build AND revision_id=p_build EXCEPT ALL SELECT "record_id","native_type","family","native_address","native_address_stream_id",convert_to("scalars_json"::text,'UTF8'),convert_to("structure_json"::text,'UTF8') FROM kb.pdf_record_native WHERE product_id=prior_ AND revision_id=prior_) UNION ALL (SELECT "record_id","native_type","family","native_address","native_address_stream_id",convert_to("scalars_json"::text,'UTF8'),convert_to("structure_json"::text,'UTF8') FROM kb.pdf_record_native WHERE product_id=prior_ AND revision_id=prior_ EXCEPT ALL SELECT "record_id","native_type","family","native_address","native_address_stream_id",convert_to("scalars_json"::text,'UTF8'),convert_to("structure_json"::text,'UTF8') FROM kb.pdf_record_native WHERE product_id=p_build AND revision_id=p_build))
