 IF p_fold THEN
  state_:=ops.pdf_identity_fold_step(state_,count_,frame_);
 ELSE RETURN NEXT frame_; END IF;
 count_:=count_+1; length_:=length_+octet_length(frame_);
 FOR row_ IN
