ge_no' AND (jsonb_typeof(occurrence->'page_no') IS DISTINCT FROM 'number' OR occurrence->>'page_no' !~ '^[0-9]+$')) OR (occurrence ? 'page_no' AND (occurrence->>'page_no')::numeric < 1) OR (occurrence ? 'text' AND (jsonb_typeof(occurrence->'text') IS DISTINCT FROM 'string')) OR (occurrence ? 'start' AND (jsonb_typeof(occurrence->'start') IS DISTINCT FROM 'number' OR occurrence->>'start' !~ '^[0-9]+$')) OR (occurrence ? 'start' AND (occurrence->>'start')::numeric < 0) OR (occurrence ? 'end' AND (jsonb_typeof(occurrence->'end') IS DISTINCT FROM 'number' OR occurrence->>'end' !~ '^[0-9]+$')) OR (occurrence ? 'end' AND (occurrence->>'end')::numeric < 0) OR (occurrence ? 'region' AND (jsonb_typeof(occurrence->'region') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(occurrence->'region') key WHERE key<>ALL(ARRAY['address_space','precision','normalization','origin','left','top','right','bottom'])) OR NOT (occurrence->'region' ? 'address_space') OR (occurrence->'region' ? 'address_space' AND (jsonb_typeof(occurrence->'region'->'address_space') IS DISTINCT FROM 'string' OR occurrence->'region'->>'address_space' NOT IN ('analytical_projection','native_cell','native_item','normalized_raw','pdf_points','raw_response','recognized_text','selected_item','submitted_pixels'))) OR NOT (occurrence->'region' ? 'precision') OR (occurrence->'region' ? 'precision' AND (jsonb_typeof(occurrence->'region'->'precision') IS DISTINCT FROM 'string' OR occurrence->'region'->>'precision' NOT IN ('block','cell','coarse','glyph','inherited','item','unknown','word'))) OR NOT (occurrence->'region' ? 'normalization') OR (occurrence->'region' ? 'normalization' AND (jsonb_typeof(occurrence->'region'->'normalization') IS DISTINCT FROM 'string' OR occurrence->'region'->>'normalization' NOT IN ('clipped','inherited','none','normalized','unknown'))) OR NOT (occurrence->'region' ? 'origin') OR (occurrence->'region' ? 'origin' AND (jsonb_typeof(occurrence->'region'->'origin') IS DISTINCT FROM 'string' OR occurrence->'region'->>'origin' NOT IN ('bottom_left','top_left'))) OR NOT (occurrence->'region' ? 'left') OR (occurrence->'region' ? 'left' AND (jsonb_typeof(occurrence->'region'->'left') IS DISTINCT FROM 'number')) OR NOT (occurrence->'region' ? 'top') OR (occurrence->'region' ? 'top' AND (jsonb_typeof(occurrence->'region'->'top') IS DISTINCT FROM 'number')) OR NOT (occurrence->'region' ? 'right') OR (occurrence->'region' ? 'right' AND (jsonb_typeof(occurrence->'region'->'right') IS DISTINCT FROM 'number')) OR NOT (occurrence->'region' ? 'bottom') OR (occurrence->'region' ? 'bottom' AND (jsonb_typeof(occurrence->'region'->'bottom') IS DISTINCT FROM 'number'))))) THEN RAISE EXCEPTION 'parsing record shape differs: PdfProductOccurrence' USING ERRCODE='23514'; END IF;

  IF occurrence->>'occurrence_id'='' OR ((occurrence ? 'start')<>(occurrence ? 'end')) OR (occurrence ? 'start' AND ((occurrence->>'start')::bigint>(occurrence->>'end')::bigint OR occurrence->>'address_space' NOT IN ('native_item','recognized_text','selected_item','raw_response') OR occurrence->>'precision' IN ('unknown','coarse','block','inherited') OR (occurrence ? 'text' AND (occurrence->>'end')::bigint>char_length(occurrence->>'text')))) THEN RAISE EXCEPTION 'unqualified PDF occurrence address/range' USING ERRCODE='23514'; END IF;
